package school.magiccodex.client;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class NormalPresetOffTest{
 @TempDir Path dir;
 @Test void exactThreeStateCycleAndLabels(){int m=1;for(int i=0;i<6;i++){assertEquals(new int[]{1,2,3}[i%3],m);m=NormalPresetMode.next(m);}assertEquals("OFF",NormalPresetMode.label(3));assertThrows(IllegalArgumentException.class,()->NormalPresetMode.next(0));}
 @Test void offNeverDeletesOrRebindsEitherPresetAndPersistsBackingSelection()throws Exception{
  var one=new SpellKeySettings();one.assign(49,"flight");one.save(dir.resolve("key-settings.yml"));var two=new SpellKeySettings();two.assign(71,"wind_message");two.save(dir.resolve("key-settings-preset2.yml"));byte[] a=Files.readAllBytes(dir.resolve("key-settings.yml")),b=Files.readAllBytes(dir.resolve("key-settings-preset2.yml"));Files.writeString(dir.resolve("normal-preset.properties"),"selected=1\nfuture=keep\n");var p=new NormalSpellPresets(dir);p.confirmed(2);assertEquals(2,p.selected());var off=p.confirmed(3);assertEquals(3,p.selected());assertEquals(2,p.editing());assertTrue(two.sameAs(off));assertEquals(dir.resolve("key-settings-preset2.yml"),p.path());assertArrayEquals(a,Files.readAllBytes(p.path(1)));assertArrayEquals(b,Files.readAllBytes(p.path(2)));var saved=new Properties();try(var in=Files.newBufferedReader(dir.resolve("normal-preset.properties"))){saved.load(in);}assertEquals("keep",saved.getProperty("future"));var restored=new NormalSpellPresets(dir);assertEquals(3,restored.preferred());assertEquals(1,restored.selected());assertTrue(two.sameAs(restored.confirmed(3)));assertEquals(2,restored.editing());p.confirmed(1);assertTrue(one.sameAs(p.load()));assertArrayEquals(a,Files.readAllBytes(p.path(1)));assertArrayEquals(b,Files.readAllBytes(p.path(2)));
 }
 @Test void oldOneAndTwoSelectionFilesMigrateWithoutTouchingBindings()throws Exception{for(int selected:new int[]{1,2}){Files.writeString(dir.resolve("normal-preset.properties"),"selected="+selected+"\n");var p=new NormalSpellPresets(dir);assertEquals(selected,p.preferred());assertEquals(1,p.selected());p.confirmed(selected);assertEquals(selected,p.selected());assertFalse(Files.exists(p.path(1)));assertFalse(Files.exists(p.path(2)));}}
 @Test void offPassesPressRepeatReleaseAndDoesNotAutoResumeOrClearCooldown(){var s=state();var sent=new ArrayList<String>();s.serverResult("magical_flame",5000,0);s.inputAllowed(false);assertFalse(s.enabled());assertFalse(s.bound(49));assertFalse(s.registered("magical_flame"));for(int action:new int[]{1,2,0})assertEquals(CastingState.Kind.PASS,s.input(49,action,false,true,100,sent::add).kind());assertEquals(CastingState.Kind.PASS,s.fire("magical_flame",100,false,x->fail()).kind());s.suspend();s.resume();assertFalse(s.enabled());assertTrue(sent.isEmpty());assertEquals(4900,s.remaining("magical_flame",100));s.inputAllowed(true);assertTrue(s.enabled());assertEquals(CastingState.Kind.COOLDOWN,s.input(49,1,false,true,100,sent::add).kind());assertTrue(sent.isEmpty());}
 @Test void presetsOneAndTwoKeepPriorityAndOneActionPerHeldKey(){for(int mode:new int[]{1,2}){var s=state();s.inputAllowed(NormalPresetMode.inputAllowed(mode,false));var sent=new ArrayList<String>();assertTrue(s.input(49,1,false,true,0,sent::add).consumed());assertTrue(s.input(49,2,false,true,1,sent::add).consumed());assertEquals(1,sent.size());assertTrue(s.bound(49));}}
 @Test void combatOverrideRetainsItsFrozenKeysAndCooldowns(){assertFalse(NormalPresetMode.inputAllowed(3,false));assertTrue(NormalPresetMode.inputAllowed(3,true));var s=state();var keys=s.bindings();s.serverResult("hidden",3000,0);s.inputAllowed(false);s.inputAllowed(NormalPresetMode.inputAllowed(3,true));assertTrue(s.enabled());assertEquals(keys,s.bindings());assertEquals(3000,s.remaining("hidden",0));s.inputAllowed(NormalPresetMode.inputAllowed(3,false));assertFalse(s.enabled());assertEquals(keys,s.bindings());}
 @Test void malformedPreferenceFileCannotErasePresetBindingsOrDiscardServerSelection()throws Exception{var two=new SpellKeySettings();two.assign(71,"wind_message");two.save(dir.resolve("key-settings-preset2.yml"));var p=new NormalSpellPresets(dir);p.prepare(2);String broken="future=\\uZZZZ";Files.writeString(dir.resolve("normal-preset.properties"),broken);var applied=p.confirmed(2);assertEquals(2,p.selected());assertTrue(two.sameAs(applied));assertNotNull(p.saveFailure());assertEquals(broken,Files.readString(dir.resolve("normal-preset.properties")));assertTrue(two.sameAs(SpellKeySettings.load(p.path(2))));}
 private CastingState state(){var s=new CastingState();s.alwaysActive();s.catalog(CodexData.previewSpells());var b=new SpellKeySettings();b.assign(49,"magical_flame");s.setBindings(b);return s;}
}
